A.newPartnerSave=async()=>{const n=val('np-n').trim();if(!n){toast('اكتب الاسم');return}const k=val('np-k');const r=num('np-r');const mains=S.partners.filter(p=>p.kind==='main'&&!p.exited);
 let shares=null;if(k==='main'&&mains.length){shares=mains.map(p=>({id:p.id,share:num('ns-'+p.id)}));const t=shares.reduce((s,x)=>s+x.share,0)+r;if(Math.abs(t-100)>0.05){toast('مجموع النسب '+fmt(t,2)+'% لازم يبقى 100%');return}}
 const p={name:n,phone:val('np-ph'),capital:num('np-c'),treasury_id:val('np-t'),kind:k==='main'?'main':'temp',share:k==='main'?r:0,method:k==='main'?null:k,rate:k==='main'?0:r,start:today(),end:k==='main'?'':addMonth(curMonth(),num('np-m'))+today().slice(7)};if(shares)p.shares=shares;
 await rpc('add_partner',{p});closeSheet();await refresh();toast('اتضاف الشريك')};
A.editShares=()=>{const mains=S.partners.filter(p=>p.kind==='main'&&!p.exited);sheet(`<h2>نسب الشركاء</h2>${mains.map(p=>`<div class="row" style="flex-wrap:nowrap;margin-bottom:6px"><span style="flex:1">${esc(p.name)}</span><input type="number" class="inp-sm" id="es-${p.id}" value="${p.share}" style="width:90px">%</div>`).join('')}<button class="btn block" style="margin-top:12px" data-a="sharesSave">حفظ</button>`)};
A.sharesSave=async()=>{const mains=S.partners.filter(p=>p.kind==='main'&&!p.exited);const shares=mains.map(p=>({id:p.id,share:num('es-'+p.id)}));const t=shares.reduce((s,x)=>s+x.share,0);if(Math.abs(t-100)>0.05){toast('المجموع '+fmt(t,2)+'%، لازم 100%');return}await rpc('set_shares',{p:{shares}});closeSheet();await refresh();toast('اتحفظت النسب')};

